{{ config(
            materialized='table',
                post_hook={
                    "sql": "-- 1. Facility-to-Channel Mapping Table CREATE TEMP TABLE Facility_Channel_Mapping AS SELECT \'Keralaayurveda_BLR_01\' AS FACILITY, \'Pharmeasy\' AS CHANNEL UNION ALL SELECT \'Keralaayurveda_BLR_01\', \'India Website\' UNION ALL SELECT \'keralaayurvedamarketplace\', \'India Website\' UNION ALL SELECT \'keralaayurvedamarketplace\', \'Snapdeal\' UNION ALL SELECT \'keralaayurvedamarketplace\', \'Nykaa\' UNION ALL SELECT \'keralaayurvedamarketplace\', \'Flipkart\' UNION ALL SELECT \'keralaayurveda\', \'Amazon Seller\'; -- 2. Inventory Data Base: Extracting inventory and preserving FACILITY CREATE TEMP TABLE Inventory_Data_Base AS SELECT * FROM ( SELECT NULL AS COMPANYID, NULL AS COMPANYNAME, PARSE_DATETIME(\'%Y-%m-%dT%H:%M:%E*SZ\', timestamp) AS CREATIONDATE, PARSE_DATETIME(\'%Y-%m-%dT%H:%M:%E*SZ\', timestamp) AS LASTUPDATEDATE, DATETIME(TIMESTAMP(timestamp), \"Asia/Kolkata\") AS DATA_FETCH_DATE, REPLACE(SKUCODE, \'\\'\', \'\') AS SKU, REPLACE(SKUCODE, \'\\'\', \'\') AS ACCOUNTINGSKU, REPLACE(SKUCODE, \'\\'\', \'\') AS PRODUCTID, REPLACE(SKUCODE, \'\\'\', \'\') AS COMPANYPRODUCTID, NULL AS MODELNO, NULL AS PRODUCTUNIQUECODE, UPPER(NAME) AS PRODUCTNAME, NULL AS DESCRIPTION, NULL AS IS_COMBO, NULL AS IMAGEURL, NULL AS SIZE, UPPER(BRAND) AS BRAND, CATEGORYCODE AS CATEGORY, NULL AS COLOR, NULL AS WIDTH, NULL AS HEIGHT, NULL AS LENGTH, NULL AS WEIGHT, NULL AS MRP, NULL AS COST, FACILITY, -- Preserve the facility column NULL AS ACCOUNTINGUNIT, PUTAWAYPENDING AS RESERVEDINVENTORY, INVENTORY AS AVAILABLEINVENTORY, NULL AS INVENTORYTHRESHOLD, NULL AS SELLINGPRICETHRESHOLD, ROW_NUMBER() OVER ( PARTITION BY FACILITY, REPLACE(SKUCODE, \'\\'\', \'\'), CAST(DATETIME(TIMESTAMP(timestamp), \"Asia/Kolkata\") AS DATE) ORDER BY DATETIME(TIMESTAMP(timestamp), \"Asia/Kolkata\") DESC ) AS rw FROM MAPLEMONK.UNICOMMERCE_Uni_KA_GET_INVENTORY_SNAPSHOT ) WHERE rw = 1; -- 3. Aggregate Inventory Data by Facility CREATE TEMP TABLE Inventory_Data AS SELECT DATA_FETCH_DATE, FACILITY, SKU, PRODUCTID, PRODUCTNAME, SIZE, BRAND, CATEGORY, COLOR, SUM(IFNULL(AVAILABLEINVENTORY, 0)) AS AVAILABLEINVENTORY FROM Inventory_Data_Base GROUP BY 1,2,3,4,5,6,7,8,9; -- 4. Sales Data Daily (remains unchanged) CREATE TEMP TABLE Sales_Data_Daily AS SELECT order_date, REPLACE(SKU_CODE, \'\\'\', \'\') AS SKU, SUM(IFNULL(quantity, 0)) AS QUANTITY, SUM(IFNULL(returned_quantity, 0)) AS RETURNED_QUANTITY, SUM(IFNULL(SELLING_PRICE,0)) AS SELLING_PRICE FROM maplemonk.KA_sales_consolidated GROUP BY 1, 2; -- 5. PRE_Sales_DRR: Combine Sales and Inventory Data CREATE TEMP TABLE PRE_Sales_DRR AS SELECT CAST(COALESCE(order_date, DATA_FETCH_DATE) AS DATE) AS Date, COALESCE(ID.SKU, SD.SKU) AS SKU, IFNULL(SD.QUANTITY, 0) AS Quantity, IFNULL(ID.AVAILABLEINVENTORY, 0) AS Available_Inventory, CASE WHEN IFNULL(ID.AVAILABLEINVENTORY, 0) > IFNULL(SD.QUANTITY, 0) THEN 1 ELSE 0 END AS drr_flag FROM Sales_Data_Daily SD FULL OUTER JOIN Inventory_Data ID ON CAST(ID.DATA_FETCH_DATE AS DATE) = CAST(SD.order_date AS DATE) AND LOWER(ID.SKU) = LOWER(SD.SKU); -- 6. Final_DRR: Aggregating DRR flags over a 30-day window CREATE TEMP TABLE Final_DRR AS SELECT pd.date, pd.sku, SUM(CASE WHEN pdr.drr_flag = 1 THEN pdr.Quantity ELSE 0 END) AS drr_quantity, SUM(pdr.drr_flag) AS drr_days FROM PRE_Sales_DRR pd LEFT JOIN PRE_Sales_DRR pdr ON pd.sku = pdr.sku AND DATE_DIFF(pd.date, pdr.date, DAY) <= 30 AND DATE_DIFF(pd.date, pdr.date, DAY) > 0 GROUP BY 1,2; -- 7. Sales_Data_Max_Weekly: Maximum weekly sales per SKU (across all channels) CREATE TEMP TABLE Sales_Data_Max_Weekly AS WITH WeeklySales AS ( SELECT DATE_TRUNC(order_date, WEEK) AS week_Start, REPLACE(SKU_CODE, \'\\'\', \'\') AS SKU, SUM(IFNULL(quantity, 0)) AS QUANTITY, SUM(IFNULL(returned_quantity, 0)) AS RETURNED_QUANTITY, SUM(IFNULL(SELLING_PRICE,0)) AS SELLING_PRICE FROM maplemonk.KA_sales_consolidated WHERE DATE_DIFF(CURRENT_DATE(), order_date, DAY) <= 56 GROUP BY 1, 2 ) SELECT week_Start, SKU, QUANTITY, RETURNED_QUANTITY FROM ( SELECT week_Start, SKU, QUANTITY, RETURNED_QUANTITY, SELLING_PRICE, ROW_NUMBER() OVER (PARTITION BY SKU ORDER BY QUANTITY DESC) AS ranking FROM WeeklySales ) WHERE ranking = 1; -- 8. Sales_Data_Min_Weekly: Minimum weekly sales per SKU (across all channels) CREATE TEMP TABLE Sales_Data_Min_Weekly AS WITH WeeklySales AS ( SELECT DATE_TRUNC(order_date, WEEK) AS week_Start, REPLACE(SKU_CODE, \'\\'\', \'\') AS SKU, SUM(IFNULL(quantity, 0)) AS QUANTITY, SUM(IFNULL(returned_quantity, 0)) AS RETURNED_QUANTITY, SUM(IFNULL(SELLING_PRICE,0)) AS SELLING_PRICE FROM maplemonk.KA_sales_consolidated WHERE DATE_DIFF(CURRENT_DATE(), order_date, DAY) <= 56 GROUP BY 1, 2 ) SELECT week_Start, SKU, QUANTITY, RETURNED_QUANTITY, SELLING_PRICE FROM ( SELECT week_Start, SKU, QUANTITY, RETURNED_QUANTITY, SELLING_PRICE, ROW_NUMBER() OVER (PARTITION BY SKU ORDER BY QUANTITY) AS ranking FROM WeeklySales ) WHERE ranking = 1; -- 9. Sales_56avg_w_Inv: Combine inventory and 56-day sales, now preserving FACILITY CREATE TEMP TABLE Sales_56avg_w_Inv AS SELECT ID.DATA_FETCH_DATE, ID.FACILITY, ID.SKU, ID.PRODUCTID, UPPER(CAST(ID.PRODUCTNAME AS STRING)) AS Product_Final_Name, UPPER(CAST(ID.CATEGORY AS STRING)) AS Category, UPPER(CAST(ID.COLOR AS STRING)) AS COLOR, MAX(IFNULL(CAST(ID.AVAILABLEINVENTORY AS FLOAT64), 0)) AS Available_Inventory, SUM(IFNULL(CAST(SD56.QUANTITY AS FLOAT64), 0)) AS Sold_Quantity_56_Days, SUM(IFNULL(CAST(SD56.SELLING_PRICE AS FLOAT64), 0)) AS Selling_Price_56_Days, MAX(IFNULL(CAST(SWMax.QUANTITY AS FLOAT64), 0)) AS Max_Weekly_Sales, MAX(IFNULL(CAST(SWMin.QUANTITY AS FLOAT64), 0)) AS Min_Weekly_Sales FROM Inventory_Data ID LEFT JOIN Sales_Data_Daily SD56 ON ID.SKU = SD56.SKU AND DATE_DIFF(IFNULL(ID.DATA_FETCH_DATE, CURRENT_DATE()), SD56.ORDER_DATE, DAY) BETWEEN 1 AND 56 LEFT JOIN Sales_Data_Max_Weekly SWMax ON ID.SKU = SWMax.SKU LEFT JOIN Sales_Data_Min_Weekly SWMin ON ID.SKU = SWMin.SKU GROUP BY DATA_FETCH_DATE, ID.FACILITY, ID.SKU, ID.PRODUCTID, UPPER(CAST(ID.PRODUCTNAME AS STRING)), UPPER(CAST(ID.CATEGORY AS STRING)), UPPER(CAST(ID.COLOR AS STRING)); -- 10. Sales_56_14_Avg_w_Inv: Adding 14-day sales, preserving FACILITY CREATE TEMP TABLE Sales_56_14_Avg_w_Inv AS SELECT DATA_FETCH_DATE, FACILITY, SD56.SKU, PRODUCTID, Product_Final_Name, Category, COLOR, Available_Inventory, Max_Weekly_Sales, Min_Weekly_Sales, Sold_Quantity_56_Days, Selling_Price_56_Days, SUM(IFNULL(SD14.QUANTITY, 0)) AS Sold_Quantity_14_Days, SUM(IFNULL(SD14.SELLING_PRICE, 0)) AS Selling_Price_14_Days FROM Sales_56avg_w_Inv SD56 LEFT JOIN Sales_Data_Daily SD14 ON SD56.SKU = SD14.SKU AND DATE_DIFF(IFNULL(SD56.DATA_FETCH_DATE, CURRENT_DATE()), SD14.ORDER_DATE, DAY) BETWEEN 1 AND 14 GROUP BY DATA_FETCH_DATE, FACILITY, SD56.SKU, PRODUCTID, Product_Final_Name, Category, COLOR, Available_Inventory, Max_Weekly_Sales, Min_Weekly_Sales, Sold_Quantity_56_Days, Selling_Price_56_Days; -- 11. Sales_56_14_mtd_Avg_w_Inv: Adding month-to-date (MTD) sales CREATE TEMP TABLE Sales_56_14_mtd_Avg_w_Inv AS SELECT DATA_FETCH_DATE, FACILITY, SD56.SKU, PRODUCTID, Product_Final_Name, Category, COLOR, Available_Inventory, Max_Weekly_Sales, Min_Weekly_Sales, Sold_Quantity_56_Days, Selling_Price_56_Days, Sold_Quantity_14_Days, Selling_Price_14_Days, SUM(IFNULL(SDmtd.QUANTITY, 0)) AS sold_quantity_mtd, SUM(IFNULL(SDmtd.Selling_Price, 0)) AS Selling_Price_mtd FROM Sales_56_14_Avg_w_Inv SD56 LEFT JOIN Sales_Data_Daily SDmtd ON SD56.SKU = SDmtd.SKU AND DATE_TRUNC(SDmtd.ORDER_DATE - INTERVAL 1 DAY, MONTH) = DATE_TRUNC(IFNULL(SD56.DATA_FETCH_DATE, CURRENT_DATE()), MONTH) AND SDmtd.ORDER_DATE < IFNULL(SD56.DATA_FETCH_DATE, CURRENT_DATE()) GROUP BY DATA_FETCH_DATE, FACILITY, SD56.SKU, PRODUCTID, Product_Final_Name, Category, COLOR, Available_Inventory, Max_Weekly_Sales, Min_Weekly_Sales, Sold_Quantity_56_Days, Selling_Price_56_Days, Sold_Quantity_14_Days, Selling_Price_14_Days; -- 12. Sales_56_14_mtd_7_Avg_w_Inv: Adding 7-day sales CREATE TEMP TABLE Sales_56_14_mtd_7_Avg_w_Inv AS SELECT DATA_FETCH_DATE, FACILITY, EXTRACT(DAY FROM DATE_SUB(DATA_FETCH_DATE, INTERVAL 1 DAY)) AS mtd_Days, SD56_14.SKU, PRODUCTID, Product_Final_Name, Category, COLOR, Available_Inventory, Max_Weekly_Sales, Min_Weekly_Sales, Sold_Quantity_56_Days, Selling_Price_56_Days, Sold_Quantity_14_Days, Selling_Price_14_Days, sold_quantity_mtd, Selling_Price_mtd, SUM(IFNULL(SD7.QUANTITY, 0)) AS Sold_Quantity_7_Days, SUM(IFNULL(SD7.SELLING_PRICE, 0)) AS Selling_Price_7_Days FROM Sales_56_14_mtd_Avg_w_Inv SD56_14 LEFT JOIN Sales_Data_Daily SD7 ON SD56_14.SKU = SD7.SKU AND DATE_DIFF(IFNULL(SD56_14.DATA_FETCH_DATE, CURRENT_DATE()), SD7.ORDER_DATE, DAY) BETWEEN 1 AND 7 GROUP BY DATA_FETCH_DATE, FACILITY, mtd_Days, SD56_14.SKU, PRODUCTID, Product_Final_Name, Category, COLOR, Available_Inventory, Max_Weekly_Sales, Min_Weekly_Sales, Sold_Quantity_56_Days, Selling_Price_56_Days, Sold_Quantity_14_Days, Selling_Price_14_Days, sold_quantity_mtd, Selling_Price_mtd; -- 13. Sales_56_14_mtd_30_7_Avg_w_Inv: Adding 30-day sales CREATE TEMP TABLE Sales_56_14_mtd_30_7_Avg_w_Inv AS SELECT DATA_FETCH_DATE, FACILITY, mtd_Days, SD56_14_7.SKU, PRODUCTID, Product_Final_Name, Category, COLOR, Available_Inventory, Max_Weekly_Sales, Min_Weekly_Sales, Sold_Quantity_56_Days, Selling_Price_56_Days, Sold_Quantity_14_Days, Selling_Price_14_Days, sold_quantity_mtd, Selling_Price_mtd, Sold_Quantity_7_Days, Selling_Price_7_Days, SUM(IFNULL(SD30.QUANTITY, 0)) AS Sold_Quantity_30_Days, SUM(IFNULL(SD30.SELLING_PRICE, 0)) AS Selling_Price_30_Days FROM Sales_56_14_mtd_7_Avg_w_Inv SD56_14_7 LEFT JOIN Sales_Data_Daily SD30 ON SD56_14_7.SKU = SD30.SKU AND DATE_DIFF(IFNULL(SD56_14_7.DATA_FETCH_DATE, CURRENT_DATE()), SD30.ORDER_DATE, DAY) BETWEEN 1 AND 30 GROUP BY DATA_FETCH_DATE, FACILITY, mtd_Days, SD56_14_7.SKU, PRODUCTID, Product_Final_Name, Category, COLOR, Available_Inventory, Max_Weekly_Sales, Min_Weekly_Sales, Sold_Quantity_56_Days, Selling_Price_56_Days, Sold_Quantity_14_Days, Selling_Price_14_Days, sold_quantity_mtd, Selling_Price_mtd, Sold_Quantity_7_Days, Selling_Price_7_Days; -- 14. INVENTORY_FINAL: Combine all sales aggregates with inventory CREATE TEMP TABLE INVENTORY_FINAL AS SELECT DATA_FETCH_DATE, FACILITY, mtd_Days, SD56_14_7_30.SKU, PRODUCTID, Product_Final_Name, Category, COLOR, Available_Inventory, Max_Weekly_Sales, Min_Weekly_Sales, Sold_Quantity_56_Days, Selling_Price_56_Days, Sold_Quantity_14_Days, Selling_Price_14_Days, sold_quantity_mtd, Selling_Price_mtd, Sold_Quantity_7_Days, Selling_Price_7_Days, Sold_Quantity_30_Days, Selling_Price_30_Days, SUM(IFNULL(SD1.QUANTITY, 0)) AS Sold_Quantity_last_day, SUM(IFNULL(SD1.SELLING_PRICE, 0)) AS Selling_Price_last_day FROM Sales_56_14_mtd_30_7_Avg_w_Inv SD56_14_7_30 LEFT JOIN Sales_Data_Daily SD1 ON SD56_14_7_30.SKU = SD1.SKU AND DATE_DIFF(IFNULL(SD56_14_7_30.DATA_FETCH_DATE, CURRENT_DATE()), SD1.ORDER_DATE, DAY) = 1 GROUP BY DATA_FETCH_DATE, FACILITY, mtd_Days, SD56_14_7_30.SKU, PRODUCTID, Product_Final_Name, Category, COLOR, Available_Inventory, Max_Weekly_Sales, Min_Weekly_Sales, Sold_Quantity_56_Days, Selling_Price_56_Days, Sold_Quantity_14_Days, Selling_Price_14_Days, sold_quantity_mtd, Selling_Price_mtd, Sold_Quantity_7_Days, Selling_Price_7_Days, Sold_Quantity_30_Days, Selling_Price_30_Days; -- 15. Final Fact Table: Join with SKU_MASTER, Final_DRR and the Facility-Channel mapping CREATE OR REPLACE TABLE MAPLEMONK.KA_INVENTORY_FACT_ITEMS AS SELECT IFT.DATA_FETCH_DATE, IFT.mtd_Days, IFT.FACILITY, FCM.CHANNEL, IFT.SKU, IFT.PRODUCTID, COALESCE(SM.NAME, IFT.Product_Final_Name) AS Product_Final_Name, COALESCE(SM.CATEGORY, IFT.Category) AS Category, IFT.COLOR, SM.SUB_CATEGORY, IFT.Available_Inventory, IFT.Max_Weekly_Sales, IFT.Min_Weekly_Sales, IFT.Sold_Quantity_56_Days, IFT.Selling_Price_56_Days, IFT.Sold_Quantity_30_Days, IFT.Selling_Price_30_Days, IFT.Sold_Quantity_14_Days, IFT.Selling_Price_14_Days, IFT.sold_quantity_mtd, IFT.Selling_Price_mtd, IFT.Sold_Quantity_7_Days, IFT.Selling_Price_7_Days, IFT.Sold_Quantity_last_day, IFT.Selling_Price_last_day, FD.drr_quantity, FD.drr_days FROM INVENTORY_FINAL IFT LEFT JOIN ( SELECT * FROM ( SELECT *, ROW_NUMBER() OVER (PARTITION BY skucode ORDER BY 1) AS rw FROM MAPLEMONK.SKU_MASTER ) WHERE rw = 1 ) SM ON LOWER(IFT.SKU) = LOWER(SM.skucode) LEFT JOIN Final_DRR FD ON CAST(IFT.DATA_FETCH_DATE AS DATE) = CAST(FD.date AS DATE) AND LOWER(IFT.SKU) = LOWER(FD.sku) LEFT JOIN Facility_Channel_Mapping FCM ON IFT.FACILITY = FCM.FACILITY WHERE IFT.SKU NOT IN ( \'5J-FTEO-KY90\', \'8906000970102_KRLMP\', \'8906000973059_KRLMP\', \'ABC-12345-S-BA\', \'ABC-12345-S-BF\', \'ACF\', \'F1ARA0130\', \'F1ARA0130R-3\', \'F1ARA0230-1\', \'F1ARA0230-2\', \'F1ARA0230-3\', \'F1ARA0430-1\', \'F1ARA0430-2\', \'F1ARA0430-3\', \'F1ARA0530\', \'F1ARA0930\', \'F1ARA1230\', \'F1ARA1430\', \'F1ARA1930\', \'F1ASA0530\', \'F1ASA1030\', \'F1CHA0110-P3_1\', \'F1CHA0110-1\', \'F1CHA0210-1\', \'F1CHA1210_P3_1\', \'F1CHA1910\', \'F1CHA2310_1\', \'F1CHA2310_4\', \'F1CHA2310_P3_1\', \'F1CRB0306_P3\', \'F1GRA1513_2\', \'F1GRA1513_2_1\', \'F1GRA2113_2\', \'F1GRA2113_2_1\', \'F1GUA0110_2\', \'F1GUA1511_2\', \'F1GUA1610-2\', \'F1GUA1610-3\', \'F1GUA0210-2\', \'F1KTA0818\', \'F1KTA27412\', \'F1KUB1214_2\', \'F1KWA0214-2\', \'F1KWA0214-3\', \'F1KWA0314_N\', \'F1KWA0514-2\', \'F1KWA0514-3\', \'F1KWA0714-2\', \'F1KWA0714-3\', \'F1KWA1014-2\', \'F1KWA1014-3\', \'F1KWA1314_2\', \'F1KWA1514_3C\', \'F1KWA1614_N\', \'F1KWA2314_R\', \'F1KWA3214_2C\', \'F1KWA3314-2\', \'F1KWA4114-2\', \'F1KWA4114-3\', \'F1KWA4314_2\', \'F1LEA0118_2\', \'F1LEA0318_2C-ES\', \'F1LEA0318_2C-ES_1\', \'F1LEA1212_P3_1\', \'F1RAA0115-2\', \'F1RAA0115-3\', \'F1THA0103-P3\', \'F1THA0103-P3_1\', \'F1THA0103_4\', \'F1THA2003_P3_1\', \'F1THA2112_2\', \'F1THA2112_3C\', \'F1THB0212-P3_1\', \'F1THB0614_2\', \'F1THB1812_P3_1\', \'F1THB2212\', \'F1THB3414_2\', \'F1THB5014_2\', \'F1THB6514_2C-ES\', \'F1THB6514_3C-ES\', \'F1THB6514_3C-ES_1\', \'F1THB6614_2\', \'F1THB7508_2C\', \'F1THB7508_2C_1\', \'F1THB7614_2\', \'F1THB8112_2_1\', \'F1THB8112_3\', \'F1THB8112_3C\', \'F1THB8112_6C\', \'F1THB8114_2C\', \'F1THB8114_2C_1\', \'F1THB8114_3C\', \'F1THB8114_3C_1\', \'F1THB8114_6C\', \'F1THB8114_6C_1\', \'F1THB8117_2\', \'F1THB8117_2_1\', \'F1THBO212\', \'F1THIA9815\', \'F1THKEEH\', \'F1TIA9815-P2\', \'F1TIA9815-P4\', \'F1TIA9815_2\', \'F1VAA0210_P3_1\', \'F1VAA0210_P6\', \'F1VAAO210\', \'F2CAA0209_2C-ES_1\', \'F2CAA0209_3C-ES_1\', \'F2CAA0312_3C-ES\', \'F2CAA0412_2C-ES_1\', \'F2CAA0412_3C-ES_1\', \'F2CAA0512_2C-ES_1\', \'F2CAA0512_3C-ES_1\', \'F2CAA0612_2C-ES_1\', \'F2CAA0612_3C-ES_1\', \'F2CRB0106_2\', \'F2CRB0106_2C\', \'F2CRB0106_2C-ES_1\', \'F2CRB0106_2C-ES_2\', \'F2CRB0106_2C-ES_3\', \'F2CRB0106_3C-ES_1\', \'F2CRB0106_3C-ES_1_1\', \'F2CRB0106_N\', \'F2CRB0306_2C-ES\', \'F2OPA0115_2C-ES_1\', \'F2OPA0115_3C-ES_1\', \'F2OPA0618_2C-ES_1\', \'F2OPA0618_3C-ES_1\', \'F2OPA0618_SF\', \'F2OPA1000_2\', \'F2SYA0114-2\', \'F2SYA0114-3\', \'F2SYA0114_3C-ES_1\', \'F2SYA0314_2C-ES_1\', \'F2SYA0314_3C-ES_1\', \'F2SYA0412_2C-ES_1\', \'F2TAA0512_2C-ES_1\', \'F2TAA0512_3C-ES_1\', \'F2TAA1812_2\', \'F2TAA1812_2_1\', \'F2TAA1912_R\', \'F2TAA2908_2C-ES_1\', \'F2TAA2908_3C-ES_1\', \'F2TAA3008_2C-ES_1\', \'F2TAA3008_3C-ES_1\', \'F2THA1711_2C\', \'F2THA1711_3\', \'F2THA1711_3C\', \'F2THA1711_6\', \'F2THA1711_6C\', \'F2THA1711_P3\', \'F2THA1711_SF\', \'F2THA1714_2\', \'F2THA1714_2_1\', \'F2THA1814\', \'F2THA1815_2C-ES_1\', \'F2THA1815_3C-ES_1\', \'F2THB2012_2C\', \'F2THB2012_2C_1\', \'F2THB2012_3C\', \'F2THB2012_6C\', \'F2THB2012_6C_1\', \'FCSPA0103\', \'FCSPA0203\', \'FCSPA0303\', \'FCSPA0403\', \'FID\', \'FAK-KAL\', \'HHKM-001\', \'HHKM-001_1\', \'HHKM-002\', \'HHKM-002_2\', \'HHKM-003\', \'HHKM-003_3\', \'HHKW-001\', \'HHKW-002\', \'HHKW-002_2\', \'HHKW-003\', \'HHKW-003_3\', \'IBK\', \'ISK-001\', \'ISK-002\', \'ISK-003\', \'KLA-28-07-2023-1\', \'KLA-28-07-2023-2\', \'KLA-B-450\', \'KLA-B-470\', \'KA-001\', \'KA-002\', \'KA-003\', \'KA-004\', \'KA-005\', \'KA-006\', \'KA-007\', \'KA-008\', \'KA-009\', \'KA-010\', \'KA-011\', \'KA-012\', \'KA-013\', \'KA